import json, itertools
comp={'A':'U','U':'A','C':'G','G':'C'}
# full GC stems, vary closing pair type, loop, tetraloop, spacer, idx0
def build(o5, c5c14, loop, tet, sp, i0):
    s=['A']*40
    s[0]=i0
    for j,i in enumerate([1,2,3,4]):
        s[i]=o5[j]; s[33-i]=comp[o5[j]]
    s[5]=c5c14[0]; s[14]=c5c14[1]
    for k,b in enumerate(loop): s[6+k]=b
    for j,i in enumerate([15,16,17,18]):
        s[i]='GCGC'[j]; s[41-i]=comp['GCGC'[j]]
    for k,b in enumerate(tet): s[19+k]=b
    s[27]=sp[0]; s[28]=sp[1]
    return ''.join(s)
cands=[]
wc=[('G','C'),('C','G'),('G','U'),('U','G'),('A','U'),('U','A')]
